def max_sum(arr: List[int]) -> int:
    """
    Return the maximum sum of a bitonic subsequence in `arr`.
    A bitonic subsequence first strictly increases and then strictly decreases.
    """
    n = len(arr)
    if n == 0:
        return 0

    # Maximum sum of an increasing subsequence ending at each index
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]                     # subsequence consisting of arr[i] only
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Maximum sum of a decreasing subsequence starting at each index
    dec = [0] * n
    for i in reversed(range(n)):
        dec[i] = arr[i]                     # subsequence consisting of arr[i] only
        for k in range(i + 1, n):
            if arr[k] < arr[i]:
                dec[i] = max(dec[i], dec[k] + arr[i])

    # Combine to form a bitonic subsequence with peak at i
    best = float('-inf')
    for i in range(n):
        # arr[i] counted twice, subtract once
        best = max(best, inc[i] + dec[i] - arr[i])

    return best

