        return 0

    # Max sum increasing subsequence ending at each index
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # Max sum decreasing subsequence starting at each index
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # Combine: inc + dec - arr[i] (arr[i] counted twice)
    best = 0
    for i in range(n):
        best = max(best, inc[i] + dec[i] - arr[i])

    return best


