def set_left_most_unset_bit(n: int) -> int:
    """
    Return the integer obtained by setting the most significant unset (0) bit
    in the binary representation of n. If n is already all ones (e.g. 7 -> 111),
    the next higher bit is set.
    """
    if n < 0:
        raise ValueError("n must be non‑negative")

    # Handle the special case of n == 0 separately
    if n == 0:
        return 1  # set the least significant bit

    # Scan from the most significant bit downwards
    for i in reversed(range(n.bit_length())):
        if not (n >> i) & 1:
            return n | (1 << i)

    # All bits up to the current most significant bit are set to 1;
    # set the next higher bit.
    return n | (1 << n.bit_length())


