def max_Product(nums: List[int]) -> Tuple[int, int]:
    """
    Return a pair of integers from the list that yields the maximum product.
    If multiple pairs give the same maximum product, any one of them is returned.
    """
    if len(nums) < 2:
        raise ValueError("At least two numbers are required")

    # Track the two largest positive numbers
    max1: Optional[int] = None
    max2: Optional[int] = None

    # Track the two smallest (most negative) numbers
    min1: Optional[int] = None
    min2: Optional[int] = None

    for n in nums:
        # Update largest positives
        if n >= 0:
            if max1 is None or n > max1:
                max2 = max1
                max1 = n
            elif max2 is None or n > max2:
                max2 = n

        # Update smallest negatives
        if n <= 0:
            if min1 is None or n < min1:
                min2 = min1
                min1 = n
            elif min2 is None or n < min2:
                min2 = n

    candidates: List[Tuple[int, int]] = []

    if max1 is not None and max2 is not None:
        candidates.append((max1, max2))

    if min1 is not None and min2 is not None:
        candidates.append((min1, min2))

    # If all numbers are positive or all are negative, we still have candidates
    if not candidates:
        # All numbers are zero? return any two zeros
        return (0, 0)

    # Choose the pair with the largest product
    best_pair = max(candidates, key=lambda p: p[0] * p[1])

    # Return the pair in ascending order for consistency
    return tuple(sorted(best_pair))

